import SwiftUI

/// One guest status: dot/icon colour, pill text and pill background (spec/design.md §2.2).
struct StatusColors {
    let fg: Color
    let text: Color
    let bg: Color
}

extension Color {
    /// Colour tokens from spec/design.md §2: `color.brand.primary` → `Color.DS.brandPrimary`.
    /// Values live in `Colors.xcassets` (Any/Dark appearances, generated by `scripts/generate-colors.swift`);
    /// `DesignTokensTests` compares every asset with design.md.
    enum DS {
        static let bgCanvas = Color("bgCanvas")
        static let bgSurface = Color("bgSurface")
        static let bgSunken = Color("bgSunken")
        static let bgRaised = Color("bgRaised")
        static let bgOverlay = Color("bgOverlay")
        static let textPrimary = Color("textPrimary")
        static let textSecondary = Color("textSecondary")
        static let textOnBrand = Color("textOnBrand")
        static let textLink = Color("textLink")
        static let borderHairline = Color("borderHairline")
        static let borderControl = Color("borderControl")
        static let borderFocus = Color("borderFocus")
        static let brandPrimary = Color("brandPrimary")
        static let brandPressed = Color("brandPressed")
        static let brandSubtle = Color("brandSubtle")
        /// Decoration only (2.15:1 on canvas) — never for text; use `accentGoldText`.
        static let accentGold = Color("accentGold")
        static let accentGoldStrong = Color("accentGoldStrong")
        static let accentGoldText = Color("accentGoldText")
        static let accentGoldSubtle = Color("accentGoldSubtle")
        static let feedbackDanger = Color("feedbackDanger")
        static let feedbackDangerBg = Color("feedbackDangerBg")
        static let feedbackSuccess = Color("feedbackSuccess")
        static let feedbackSuccessBg = Color("feedbackSuccessBg")
        static let feedbackWarning = Color("feedbackWarning")
        static let feedbackWarningBg = Color("feedbackWarningBg")
        /// Only the WhatsApp glyph itself.
        static let whatsapp = Color("whatsapp")

        static let statusComing = status("Coming")
        static let statusDeclined = status("Declined")
        static let statusViewed = status("Viewed")
        static let statusPending = status("Pending")
        static let statusUnsent = status("Unsent")

        private static func status(_ name: String) -> StatusColors {
            StatusColors(fg: Color("status\(name)Fg"), text: Color("status\(name)Text"), bg: Color("status\(name)Bg"))
        }

        /// design.md token name → asset name, for the comparison test.
        static var tokens: [String: String] {
            var map: [String: String] = [:]
            for token in [
                "bg.canvas", "bg.surface", "bg.sunken", "bg.raised", "bg.overlay",
                "text.primary", "text.secondary", "text.onBrand", "text.link",
                "border.hairline", "border.control", "border.focus",
                "brand.primary", "brand.pressed", "brand.subtle",
                "accent.gold", "accent.goldStrong", "accent.goldText", "accent.goldSubtle",
                "feedback.danger", "feedback.dangerBg", "feedback.success", "feedback.successBg",
                "feedback.warning", "feedback.warningBg", "whatsapp",
            ] {
                map["color.\(token)"] = assetName(token.split(separator: "."))
            }
            for status in ["coming", "declined", "viewed", "pending", "unsent"] {
                for part in ["fg", "text", "bg"] {
                    map["color.status.\(status).\(part)"] = assetName(["status", Substring(status), Substring(part)])
                }
            }
            return map
        }

        private static func assetName(_ parts: [Substring]) -> String {
            parts.enumerated().map { $0.offset == 0 ? String($0.element) : $0.element.prefix(1).uppercased() + $0.element.dropFirst() }.joined()
        }
    }
}
